fn encode(message: Vec<char>) -> Vec<char> {
    // Define the vowel mapping
    let vowel_mapping: [(char, char); 5] = [
        ('a', 'c'), ('e', 'g'), ('i', 'k'), ('o', 'q'), ('u', 'w'),
    ];
    let vowel_mapping_upper: [(char, char); 5] = [
        ('A', 'C'), ('E', 'G'), ('I', 'K'), ('O', 'Q'), ('U', 'W'),
    ];

    // Create a new vector to hold the result
    let mut result = Vec::with_capacity(message.len());

    for &ch in &message {
        match ch {
            ' ' => result.push(' '), // Keep spaces as spaces
            'a' | 'e' | 'i' | 'o' | 'u' => {
                // Transform lowercase vowels
                let transformed = vowel_mapping.iter()
                    .find(|&&(v, _)| v == ch)
                    .map(|&(_, new_ch)| new_ch.to_ascii_uppercase())
                    .unwrap_or(ch);
                result.push(transformed);
            },
            'A' | 'E' | 'I' | 'O' | 'U' => {
                // Transform uppercase vowels
                let transformed = vowel_mapping_upper.iter()
                    .find(|&&(v, _)| v == ch)
                    .map(|&(_, new_ch)| new_ch.to_ascii_lowercase())
                    .unwrap_or(ch);
                result.push(transformed);
            },
            _ => {
                // For consonants, just swap the case
                if ch.is_ascii_alphabetic() {
                    if ch.is_lowercase() {
                        result.push(ch.to_ascii_uppercase());
                    } else {
                        result.push(ch.to_ascii_lowercase());
                    }
                }
            }
        }
    }

    result
}